 await account('employee-mohammad');assert.equal(doc.querySelector('#positionCloseoutHistory').textContent,'');assert.equal((await window.PanelWorkflow.api('/api/org/position-closeouts')).length,0);assert.equal(modelCalls,0);assert.deepEqual(errors,[]);
