async function openDesignReport(doc,id,{expandSections=true}={}){
  const button=doc.querySelector(`[data-show-design-analysis="${id}"]`);assert.ok(button);assert.equal(button.disabled,false);button.click();
  await eventually(()=>doc.querySelector('#designAnalysisDialog').open&&doc.querySelector('#designAnalysisDialog .design-alignment'));
  if(expandSections)doc.querySelectorAll('#designAnalysisDialog .analysis-proposal > details.analysis-collapsible').forEach(section=>section.open=true);
  return doc.querySelector('#designAnalysisDialog .design-alignment');
}

