test('HR structure forms omit project switches and submit registration and transfers using automatic unit models',async t=>{
  const {window,doc,account,errors}=await browser(t);await account('hr-demo');window.PanelWorkflow.go('organization');await window.PanelLifecycle.refresh();
  const sent=[],original=window.fetch;window.fetch=(path,options)=>{if(options?.method==='POST'&&['/api/org/people','/api/org/positions'].includes(path))sent.push({path,body:JSON.parse(options.body)});return original(path,options);};
  const create=doc.querySelector('#personCreateForm'),position=doc.querySelector('#positionForm');
  assert.equal(create.elements.hasProjects,undefined);assert.equal(position.elements.hasProjects,undefined);assert.equal(position.querySelector('h2').textContent,'جابجایی');
  create.elements.unitId.value='ops';create.elements.unitId.dispatchEvent(new window.Event('change'));
  create.elements.name.value='نیروی خودکار فرم واحد';create.elements.jobTitle.value='کارشناس عملیات';create.elements.jobLevel.value='کارشناس';create.elements.managerId.value='manager-ops';create.elements.sectionId.value=[...create.elements.sectionId.options].find(row=>row.value)?.value||'';
  create.elements.baseSalary.value='60000000';create.elements.duties.value='پیگیری عملیات';create.elements.effectiveFrom.value=window.PanelDate.today();
  await create.onsubmit({target:create,preventDefault(){}});
  const person=window.PanelWorkflow.accounts.find(row=>row.name==='نیروی خودکار فرم واحد');assert.ok(person);
  position.elements.employeeId.value=person.id;position.elements.employeeId.dispatchEvent(new window.Event('change'));position.elements.duties.value='شرح وظایف جدید';position.elements.effectiveFrom.value=window.PanelDate.today();position.elements.jobLevel.value='کارشناس';
  position.elements.sectionId.value=[...position.elements.sectionId.options].find(row=>row.value)?.value||'';
  await position.onsubmit({target:position,preventDefault(){}});
  assert.equal(sent.length,2);for(const {body} of sent)assert.equal(Object.hasOwn(body,'hasProjects'),false);
  const positions=await window.PanelWorkflow.api('/api/org/positions');const submitted=positions.filter(row=>row.employeeId===person.id);assert.equal(submitted.length,2,JSON.stringify({sent,status:doc.querySelector('#workflowStatus').textContent}));assert.ok(submitted.every(row=>row.hasProjects===true));assert.deepEqual(errors,[]);
});

test('onboarding hides manager-only exclusions, reuses calendar, speaks toman amount and generates section IDs',async t=>{
  const {window,doc,account,dir,errors}=await browser(t,{runModel:async()=>{throw Error('No live model');}});await account('hr-demo');window.PanelWorkflow.go('organization');await window.PanelLifecycle.refresh();
  const wordsAsset=await window.fetch('/src/persian-money.js');assert.equal(wordsAsset.status,200);assert.match(await wordsAsset.text(),/PanelMoneyWords/);
  const form=doc.querySelector('#personCreateForm'),unit=form.elements.unitId,role=form.elements.role,calendar=doc.querySelector('#new-person-start-calendar'),salary=form.elements.baseSalary,words=doc.querySelector('#newPersonSalaryWords');
  const labels=[...form.querySelector('.form-grid').children].filter(el=>el.tagName==='LABEL');assert.equal(labels.findIndex(el=>el.contains(unit)),labels.findIndex(el=>el.contains(form.elements.jobTitle))+1);assert.match(form.elements.effectiveFrom.closest('label').textContent,/تاریخ شروع به کار/);assert.equal(form.elements.effectiveFrom.readOnly,true);
  unit.value='ops';unit.dispatchEvent(new window.Event('change'));salary.value='90000000';salary.dispatchEvent(new window.Event('input'));assert.equal(words.textContent,'نود میلیون تومان');salary.value='0';salary.dispatchEvent(new window.Event('input'));assert.equal(words.textContent,'صفر تومان');salary.value='';salary.dispatchEvent(new window.Event('input'));assert.equal(words.textContent,'');
  role.value='manager';role.dispatchEvent(new window.Event('change'));for(const key of ['sectionId','duties','baseSalary','managerId']){assert.equal(form.elements[key].disabled,true);assert.equal(form.elements[key].required,false);assert.equal(form.elements[key].closest('label').hidden,true);}assert.equal(words.textContent,'');
  role.value='personnel';role.dispatchEvent(new window.Event('change'));for(const key of ['sectionId','duties','baseSalary','managerId']){assert.equal(form.elements[key].disabled,false);assert.equal(form.elements[key].required,true);assert.equal(form.elements[key].closest('label').hidden,false);}
  const createdUnit=await window.PanelWorkflow.post('/api/org/units',{id:'ui-manager-unit',name:'واحد مدیر ساختگی'});await window.PanelLifecycle.refresh();const sectionForm=doc.querySelector('#sectionForm');assert.equal(sectionForm.elements.namedItem('id'),null);sectionForm.elements.name.value='بخش ساختگی فرم';sectionForm.elements.unitId.value=createdUnit.id;await sectionForm.onsubmit({preventDefault(){},target:sectionForm});const section=(await window.PanelWorkflow.api('/api/org/sections')).find(s=>s.name==='بخش ساختگی فرم');assert.match(section.id,/^section-[\da-f-]{36}$/);
  role.value='manager';role.dispatchEvent(new window.Event('change'));unit.value=createdUnit.id;unit.dispatchEvent(new window.Event('change'));assert.equal(form.elements.sectionId.disabled,true);
  form.elements.name.value='مدیر ساختگی رابط';form.elements.jobTitle.value='مدیر واحد';form.elements.jobLevel.value='مدیر';form.elements.employeeCode.value='UI-MANAGER-TEST';form.elements.duties.value='نباید ارسال شود';salary.value='90000000';
  form.elements.effectiveFrom.click();assert.equal(calendar.hidden,false);const day=calendar.querySelector('[data-calendar-day]');day.click();assert.equal(calendar.hidden,true);assert.equal(window.PanelDate.toGregorian(form.elements.effectiveFrom.value),day.dataset.calendarDay);
  const actual=window.fetch,sent=[];window.fetch=async(path,options)=>{if(path==='/api/org/people'&&options?.method==='POST')sent.push(JSON.parse(options.body));return actual(path,options);};await form.onsubmit({preventDefault(){},target:form});assert.equal(sent.length,1);for(const key of ['sectionId','duties','baseSalary','managerId'])assert.equal(Object.hasOwn(sent[0],key),false);
  const manager=window.PanelWorkflow.accounts.find(a=>a.name==='مدیر ساختگی رابط');assert.ok(manager);assert.equal(form.elements.role.value,'personnel');assert.equal(salary.disabled,false);assert.equal(words.textContent,'');
  const store=openStore(join(dir,'db'));try{const position=store.list('position-assignment',manager.id)[0];assert.equal(position.duties,null);assert.equal(position.baseSalary,null);assert.equal(position.sectionId,null);}finally{store.close();}
  window.PanelWorkflow.go('duties');await window.PanelLifecycle.refresh();assert.doesNotMatch(doc.querySelector('#dutiesList').textContent,/مدیر ساختگی رابط/);
  await account(manager.id);window.PanelWorkflow.go('chart');await window.PanelLifecycle.refresh();assert.equal([...doc.querySelectorAll('#personalInfo dt span')].some(el=>el.textContent==='بخش'),false);assert.deepEqual(errors,[]);
});

test('personnel management position dates are calendar-only, optional dates clear and transfer starts on the selected day',async t=>{
  const {window,doc,account,dir,errors}=await browser(t,{runModel:async()=>{throw Error('No model');}});await account('hr-demo');window.PanelWorkflow.go('organization');await window.PanelLifecycle.refresh();
  assert.equal(doc.querySelector('[data-view="organization"] span').textContent,'مدیریت پرسنل');assert.equal(doc.querySelector('#view-organization h1').textContent,'مدیریت پرسنل');const form=doc.querySelector('#positionForm');
  form.elements.employeeId.value='employee-mohammad';form.elements.employeeId.dispatchEvent(new window.Event('change'));form.elements.duties.value='شرح ساختگی برای آزمون انتخاب تاریخ';form.elements.sectionId.value=[...form.elements.sectionId.options].find(o=>o.value)?.value||'';
  for(const [key,id,optional] of [['transferDate','position-transfer-calendar',true],['effectiveFrom','position-start-calendar',false],['effectiveTo','position-end-calendar',true]]){
    const input=form.elements[key],calendar=doc.querySelector('#'+id);assert.equal(input.readOnly,true);assert.equal(input.required,!optional);assert.equal(input.getAttribute('aria-controls'),id);input.click();assert.equal(calendar.hidden,false);assert.equal(!!calendar.querySelector('[data-calendar-clear]'),optional);const day=calendar.querySelectorAll('[data-calendar-day]')[optional?0:1];day.click();assert.equal(calendar.hidden,true);assert.equal(window.PanelDate.toGregorian(input.value),day.dataset.calendarDay);
    if(key==='transferDate')assert.equal(window.PanelDate.toGregorian(form.elements.effectiveFrom.value),window.PanelDate.toGregorian(input.value));
    if(optional){input.click();calendar.querySelector('[data-calendar-clear]').click();assert.equal(input.value,'');assert.equal(calendar.hidden,true);}
  }
  let sent;const actual=window.fetch;window.fetch=async(path,options)=>{if(path==='/api/org/positions'&&options?.method==='POST')sent=JSON.parse(options.body);return actual(path,options);};await form.onsubmit({preventDefault(){},target:form});assert.ok(sent);assert.equal(sent.transferDate,null);assert.equal(sent.effectiveTo,null);assert.match(sent.effectiveFrom,/^\d{4}-\d{2}-\d{2}$/);
  const store=openStore(join(dir,'db'));try{assert.ok(store.list('position-assignment','employee-mohammad').some(row=>row.status==='manager_review'&&row.duties==='شرح ساختگی برای آزمون انتخاب تاریخ'));}finally{store.close();}
  assert.equal(doc.querySelectorAll('#position-transfer-calendar').length,1);assert.deepEqual(errors,[]);
});

