 const api=window.PanelWorkflow.api,base=await api('/api/org/score-settings');let today;
 window.PanelWorkflow.api=path=>path==='/api/org/score-settings'?Promise.resolve({...base,today}):api(path);
 try{for(today of ['2025-03-20','2025-03-21','2026-10-11','2026-12-22']){
  await window.PanelScoreSettings.refresh();const form=doc.querySelector('#scoreRulesForm'),seen=[],startYear=Number(window.PanelDate.input(today).split('/')[0]),limit=new Date(Date.parse(today)+366*86400000).toISOString().slice(0,10);
  for(const year of [...form.elements.effectiveYear.options].map(o=>o.value)){form.elements.effectiveYear.value=year;form.elements.effectiveYear.dispatchEvent(new window.Event('change',{bubbles:true}));for(const season of [...form.elements.effectiveSeason.options].map(o=>o.value)){doc.querySelector('#scorePublish').disabled=false;doc.querySelector('#scorePreview').disabled=false;form.elements.effectiveSeason.value=season;form.elements.effectiveSeason.dispatchEvent(new window.Event('change',{bubbles:true}));const iso=window.PanelDate.toGregorian(year+'/'+((Number(season)-1)*3+1)+'/1');assert.equal(form.elements.effectiveDate.value,iso);assert.ok(iso>=today&&iso<=limit);assert.equal(doc.querySelector('#scorePublish').disabled,true);assert.equal(doc.querySelector('#scorePreview').disabled,true);assert.ok(doc.querySelector('#scoreEffectNote').textContent.includes(window.PanelDate.format(iso)));seen.push(iso);}}
  const expected=[startYear,startYear+1].flatMap(y=>[1,4,7,10].map(m=>window.PanelDate.toGregorian(y+'/'+m+'/1'))).filter(d=>d>=today&&d<=limit);assert.deepEqual(seen,expected);
 }}finally{window.PanelWorkflow.api=api;}
 assert.equal((await api('/api/org/score-settings')).drafts.length,base.drafts.length);assert.deepEqual(errors,[]);
