async function browser(t,{corruptStorage=false,blockedStorage=false,peerModel=false,runModel,aiDesignV2=false,autoAssessment=false}={}){
  const dir=await mkdtemp(join(tmpdir(),'kpi-panel-audit-')),server=createPanelServer({dataRoot:join(dir,'db'),uploadRoot:join(dir,'raw'),aiDesignV2,autoAssessment,...(runModel?{runModel}:{})});server.listen(0,'127.0.0.1');await once(server,'listening');
  if(peerModel){const store=openStore(join(dir,'db'));seedPeerUnitModel(store);store.close();}
  const base=`http://127.0.0.1:${server.address().port}`,errors=[],console=new VirtualConsole();console.on('jsdomError',error=>errors.push(error.message));
  const dom=new JSDOM(await readFile('index.html','utf8'),{url:base,runScripts:'outside-only',virtualConsole:console}),{window}=dom,doc=window.document;
  let pendingRequests=0,lastRequestSettled=Date.now();
  // signOut intentionally leaves loading=true while the real browser exits the
  // shell. In this non-navigating fixture its terminal signed-out marker, not
  // that loading flag, identifies completion. In-flight fetches still must stop.
  t.after(async()=>{try{await eventually(()=>pendingRequests===0&&(!window.PanelWorkflow?.working||!!doc.querySelector('#panelSignedOut')&&!window.PanelWorkflow?.user)&&!window.PanelLifecycle?.working&&Date.now()-lastRequestSettled>=300,'Browser requests must settle before disposing its document');}finally{window.close();server.closeAllConnections();await new Promise(resolve=>server.close(resolve));await rm(dir,{recursive:true,force:true});}});
  window.AbortController=globalThis.AbortController;window.indexedDB={open:()=>({})};window.scrollTo=()=>{};window.confirm=()=>true;window.fetch=async(path,options)=>{pendingRequests++;try{return path==='/api/providers'?new Response(JSON.stringify({defaultProvider:'codex',providers:[{provider:'codex',ready:false,message:'اتصال آزمایشی؛ مدل واقعی اجرا نمی‌شود.'}]}),{headers:{'Content-Type':'application/json'}}):await fetch(base+path,options);}finally{pendingRequests--;lastRequestSettled=Date.now();}};
  window.addEventListener('error',event=>errors.push(event.message));window.addEventListener('unhandledrejection',event=>errors.push(String(event.reason)));
  if(corruptStorage){window.localStorage.setItem('hamkar-users','{broken');window.localStorage.setItem('hamkar-activities','42');}
  if(blockedStorage){Object.defineProperty(window,'localStorage',{get(){throw new window.DOMException('Storage blocked','SecurityError');}});window.indexedDB={open(){throw new window.DOMException('Database blocked','SecurityError');}};}
for(const path of ['src/kpi-dashboard.js','src/app.js','src/account-security-ui.js','src/workflow-ui.js','src/persian-money.js','src/persian-date-picker.js','src/lifecycle-ui.js','src/score-settings-ui.js','src/notifications-ui.js','src/announcements-ui.js','src/ai-ui.js','src/ai-log-ui.js','src/notes-ui.js','src/chat-ui.js','src/utility-windows.js','src/theme-mode.js','src/search-ui.js'])new Script(await readFile(path,'utf8'),{filename:path}).runInContext(dom.getInternalVMContext());
  await eventually(()=>window.PanelWorkflow?.user&&!doc.querySelector('#demoRole').disabled&&doc.querySelector('.view.active'),'Panel did not start');await delay(100);
  async function account(id){if(window.PanelWorkflow.user.id===id)return;const selected=window.PanelWorkflow.accounts.find(row=>row.id===id);assert.ok(selected);doc.querySelector('#demoRole').value=selected.role;const field=doc.querySelector('#demoAccount');field.innerHTML=`<option value="${id}">${id}</option>`;field.value=id;await field.onchange({target:field});await delay(50);assert.equal(window.PanelWorkflow.user.id,id);assert.ok(doc.querySelector('.view.active'),'Account switching must leave a visible view');}
  async function period(value){const [year,month]=value.split('-');doc.querySelector('#workflowYear').value=year;doc.querySelector('#workflowYear').onchange();doc.querySelector('#workflowQuarter').value=String(Math.ceil(Number(month)/3));doc.querySelector('#workflowQuarter').onchange();doc.querySelector('#workflowMonth').value=month;await doc.querySelector('#periodForm').onsubmit({preventDefault(){}});await delay(50);}
  return {window,doc,errors,account,period,dir};
}

