test('future survey target dropdown follows the published model for the selected quarter, not the current model',async t=>{
  const {window,doc,account,period}=await browser(t);await account('hr-demo');
  const [year,month]=doc.querySelector('#workflowPeriod').value.split('-').map(Number),quarter=Math.ceil(month/3),futureQuarter=`${quarter===4?year+1:year}-Q${quarter===4?1:quarter+1}`,futureMonth=`${quarter===4?year+1:year}-${String(quarter===4?1:quarter*3+1).padStart(2,'0')}`;
  const target=window.PanelWorkflow.accounts.find(row=>row.id==='employee-mohammad');
  const draft=await window.PanelWorkflow.post('/api/org/evaluation-settings/draft',{effectiveQuarter:futureQuarter,unitId:target.unitId,weights:{exam:10,manager:20,routine:20,project:0,peer:50}});
  await window.PanelWorkflow.post('/api/org/evaluation-settings/publish',{id:draft.id});await window.PanelWorkflow.refresh();
  const includes=()=>[...(doc.querySelector('#serviceCampaignForm')?.elements.employeeId.options||[])].some(option=>option.value===target.id);
  assert.equal(includes(),false,'Future policy must not affect the current-month target list');await period(futureMonth);assert.equal(includes(),true);
  const created=await window.PanelWorkflow.post('/api/org/surveys/service',{employeeId:target.id,period:futureMonth});assert.equal(created.employeeId,target.id);assert.equal(created.status,'draft');await window.PanelWorkflow.refresh();
});

test('HR publishes a unit model through the draft list and removes it with confirmation while personnel reads switch immediately',async t=>{
  const {window,doc,account,errors}=await browser(t);await account('hr-demo');window.PanelWorkflow.go('evaluation-settings');await delay(100);
  const form=doc.querySelector('#evaluationSettingsForm'),unit=form.elements.unitId;unit.value='finance';unit.onchange();
  const target=window.PanelWorkflow.accounts.find(row=>row.id==='employee-maryam'),period=doc.querySelector('#workflowPeriod').value;
  for(const [key,value] of Object.entries({exam:25,manager:25,routine:50,project:0,peer:0}))form.elements[key].value=String(value);
  await form.onsubmit({target:form,preventDefault(){}});const publish=doc.querySelector('[data-publish-settings-draft]');assert.ok(publish);await doc.querySelector('#evaluationSettingsDrafts').onclick({target:publish});
  const button=doc.querySelector('[data-delete-settings-published]');assert.ok(button);const version=button.dataset.deleteSettingsPublished;
  const snapshot=await window.PanelWorkflow.api(`/api/workflow/employees/${target.id}?period=${period}`);assert.equal(snapshot.policyVersion,version);assert.deepEqual(snapshot.policy.weights,{exam:25,manager:25,routine:50,project:0,peer:0});
  const other=await window.PanelWorkflow.api(`/api/workflow/employees/employee-mohammad?period=${period}`);assert.notEqual(other.policyVersion,version);
  window.confirm=()=>false;await doc.querySelector('#evaluationSettingsVersions').onclick({target:button});assert.ok(doc.querySelector('[data-delete-settings-published]'));
  window.confirm=()=>true;const actual=window.fetch;let requests=0,release;const gate=new Promise(resolve=>release=resolve);
  window.fetch=async(path,options)=>{if(path==='/api/org/evaluation-settings/published/delete'){requests++;await gate;}return actual(path,options);};
  const first=doc.querySelector('#evaluationSettingsVersions').onclick({target:button});await delay(10);assert.equal(window.PanelLifecycle.working,true);const second=doc.querySelector('#evaluationSettingsVersions').onclick({target:button});release();await Promise.all([first,second]);assert.equal(requests,1);assert.equal(window.PanelLifecycle.working,false);
  assert.equal(doc.querySelector('[data-delete-settings-published]'),null);assert.doesNotMatch(doc.querySelector('#workflowStatus').textContent,/پردازش ناموفق/);
  await account(target.id);assert.notEqual((await window.PanelWorkflow.api(`/api/workflow/me?period=${period}`)).policyVersion,version);assert.deepEqual(errors,[]);
});
